(function () {
  function P(q, a, h, s) { return { q: q, a: a, h: h || "", s: s || "" }; }

  var SSC_JE_ENC2_TOMFLUIDS = {};
SSC_JE_ENC2_TOMFLUIDS.tom = [
P("For a four-bar mechanism with link lengths l=7 cm, s=3 cm, p=5 cm, q=9 cm, is it Grashof or non-Grashof?", "Non-Grashof (s+l > p+q)", "Check Grashof condition: s+l vs p+q", "Given s=3, l=9, p=5, q=7. Shortest s=3, longest l=9. s+l=12, p+q=12. Since s+l = p+q, this is the special Grashof case (change-point). However with strict inequality needed: 3+9=12 and 5+7=12 → borderline. If s+l > p+q → non-Grashof. Here s+l=12 = p+q=12, so it is a change-point mechanism (special Grashof). For proper Grashof: s+l < p+q."),
P("A four-bar mechanism has links 2, 5, 4, 6 cm. Determine if it is Grashof.", "Grashof (s+l < p+q)", "Compare shortest+longest with sum of other two", "s=2, l=6, p=5, q=4. s+l=2+6=8, p+q=5+4=9. Since 8 < 9, it satisfies Grashof condition. The shortest link (2 cm) can fully rotate."),
P("Find the degree of freedom of a four-bar mechanism using Kutzbach criterion.", "DOF = 1", "Kutzbach: DOF = 3(n−1) − 2j₁ − j₂", "n=4 links, j₁=4 lower pairs, j₂=0 higher pairs. DOF = 3(4−1) − 2(4) − 0 = 9 − 8 = 1."),
P("A planar mechanism has 8 links, 10 lower pairs, and 1 higher pair. Find its DOF.", "DOF = 0 (statically determinate structure)", "Kutzbach: DOF = 3(n−1) − 2j₁ − j₂", "DOF = 3(8−1) − 2(10) − 1 = 21 − 20 − 1 = 0. A DOF of zero means no mobility. Compare n=6, j₁=7, j₂=0 → DOF = 3(5)−14 = 1."),
P("Slider-crank: crank r=50 mm, connecting rod l=200 mm, crank angle θ=30°, ω=10 rad/s. Find piston velocity.", "v ≈ 0.304 m/s", "v = ωr(sinθ + sin2θ/2n), n=l/r=4", "n = l/r = 200/50 = 4. sin30°=0.5, sin60°=0.866. v = 10×0.05×(0.5 + 0.866/(2×4)) = 0.5×(0.5+0.10825) = 0.5×0.60825 = 0.3041 m/s. Recheck: v = ωr(sinθ + sin2θ/(2n)). v = 10×0.05×(sin30° + sin60°/(2×4)) = 0.5×(0.5 + 0.866/8) = 0.5×(0.5 + 0.10825) = 0.5×0.60825 = 0.304 m/s."),
P("Slider-crank: r=40 mm, l=160 mm, θ=60°, ω=15 rad/s. Find piston velocity.", "v ≈ 0.589 m/s", "v = ωr(sinθ + sin2θ/(2n)), n=l/r", "n = 160/40 = 4. sin60°=0.866, sin120°=0.866. v = 15×0.04×(0.866 + 0.866/(2×4)) = 0.6×(0.866+0.10825) = 0.6×0.97425 = 0.5846 m/s."),
P("Slider-crank: r=60 mm, l=240 mm, θ=45°, ω=20 rad/s. Find piston acceleration.", "a ≈ 16.97 m/s²", "a = ω²r(cosθ + cos2θ/n), n=l/r=4", "n = 240/60 = 4. cos45°=0.7071, cos90°=0. a = 400×0.06×(0.7071 + 0/4) = 24×0.7071 = 16.97 m/s²."),
P("Slider-crank: r=50 mm, l=200 mm, θ=30°, ω=10 rad/s. Find piston acceleration.", "a ≈ 4.96 m/s²", "a = ω²r(cosθ + cos2θ/n)", "n=200/50=4. cos30°=0.866, cos60°=0.5. a = 100×0.05×(0.866+0.5/4) = 5×(0.866+0.125) = 5×0.991 = 4.955 m/s²."),
P("In a Whitworth quick-return mechanism, the fixed link distance is 200 mm, crank radius is 80 mm. Find the time ratio.", "Time ratio ≈ 1.71", "QR = (180°+2α)/(180°−2α) where sinα = R/d", "d=200, R=80. sinα=80/200=0.4 → α=23.58°. Quick-return ratio = (180+2α)/(180−2α) = (180+47.16)/(180−47.16) = 227.16/132.84 = 1.71. Cutting (forward) stroke occupies the larger angle."),
P("A crank-rocker has the crank in extreme positions at α=20° from the line of fixed centres. Find the quick-return ratio.", "QR = 1.57", "QR = (180°+2α)/(180°−2α)", "Forward angle = 180°+2α = 220°, return = 180°−2α = 140°. QR = 220/140 = 1.571. Thus cutting stroke takes 61% of the cycle time."),
P("Find the rubbing velocity at an instant centre I₁₃ connecting links 1 and 3 if ω₁=5 rad/s and ω₃=2 rad/s in opposite directions, with distance from I₁₂ to I₁₃ = 120 mm.", "V_rubbing = 0.84 m/s", "V_rubbing = (ω₁+ω₃)×r when senses oppose", "Links 1 and 3 rotate in opposite directions so rubbing velocity = (ω₁+ω₃)×r = (5+2)×0.12 = 0.84 m/s. If they rotated in the same direction, V = (ω₁−ω₃)×r = 3×0.12 = 0.36 m/s."),
P("Four-bar mechanism: ω₂=10 rad/s, find ω₄ using angular velocity ratio at instant centres. Given I₂₄ distance ratio.", "ω₄ = ω₂ × (I₁₂I₂₄)/(I₁₄I₂₄)", "Angular velocity ratio theorem: ω₂/ω₄ = (I₁₄I₂₄)/(I₁₂I₂₄)", "From Kennedy theorem: I₂₄ lies on line joining I₁₂I₁₄ and I₂₃I₃₄. If I₁₂I₂₄=80mm and I₁₄I₂₄=160mm, then ω₂/ω₄ = 160/80 = 2, so ω₄ = 10/2 = 5 rad/s."),
P("A Coriolis component has ω=5 rad/s and V=3 m/s. Find the Coriolis acceleration.", "a_c = 30 m/s²", "a_c = 2ωV", "a_c = 2×5×3 = 30 m/s². Direction: rotate V vector by 90° in the direction of ω."),
P("Coriolis acceleration for a slider on a rotating link: ω=8 rad/s, sliding velocity 2 m/s. Find magnitude and direction.", "a_c = 32 m/s², direction ⊥ to sliding", "a_c = 2ωV_sliding, perpendicular to sliding direction", "a_c = 2×8×2 = 32 m/s². Direction obtained by rotating sliding velocity vector 90° in direction of angular velocity."),
P("An open belt drive has diameters 400 mm and 200 mm, centre distance 1 m. Find the angle of lap on the smaller pulley.", "θ ≈ 168.5°", "For open belt: sinα = (D₁−D₂)/(2C), θ = 180°−2α", "D₁=0.4, D₂=0.2, C=1. sinα=(0.4−0.2)/(2×1)=0.1. α=5.739°. θ = 180°−2(5.739°) = 180°−11.48° = 168.52°. In radians: θ = 2.942 rad."),
P("Cross belt drive: D₁=500 mm, D₂=250 mm, C=1.2 m. Find angle of lap on each pulley.", "θ ≈ 169.1°", "For cross belt: sinα = (D₁+D₂)/(2C), θ = 180°+2α", "sinα=(0.5+0.25)/(2×1.2)=0.75/2.4=0.3125. α=18.21°. θ=180°+2(18.21°)=216.42°=3.778 rad. Both pulleys have same lap angle in cross belt."),
P("Belt drive: tight side tension T₁=1500 N, slack side T₂=600 N, μ=0.3, θ=2.94 rad. Verify the ratio T₁/T₂.", "T₁/T₂ = 2.5, e^μθ = e^(0.3×2.94) = e^0.882 ≈ 2.416", "T₁/T₂ = e^μθ", "μθ = 0.3×2.94 = 0.882. e^0.882 = 2.416. But T₁/T₂ = 1500/600 = 2.5. Close to theoretical. Actual slightly higher due to centrifugal tension or slip."),
P("Belt drive: centrifugal tension Tc for belt mass 0.3 kg/m running at 25 m/s.", "Tc = 187.5 N", "Tc = mv²", "Tc = 0.3×25² = 0.3×625 = 187.5 N."),
P("Maximum power transmitted when T = 3Tc. If Tc=187.5 N, find maximum tension T₁.", "T₁ = 562.5 N", "At max power: T₁ = 3Tc", "T₁ = 3×187.5 = 562.5 N. The slack side T₂ = Tc = 187.5 N at maximum power condition. Power = (T₁−T₂)v = (562.5−187.5)×25 = 9375 W = 9.375 kW."),
P("Initial tension in a belt drive: T₀ = (T₁+T₂)/2. If T₁=2000 N and T₂=800 N, find T₀.", "T₀ = 1400 N", "T₀ = (T₁+T₂)/2", "T₀ = (2000+800)/2 = 1400 N. This initial tension ensures proper grip before power transmission."),
P("Flat belt friction coefficient μ=0.25, V-belt effective coefficient μ'=μ/sin(β/2) with groove angle 2β=40°. Find the ratio μ'/μ.", "μ'/μ = 2.924", "μ' = μ/sinβ, where 2β=40° so β=20°", "sin20°=0.342. μ' = 0.25/0.342 = 0.731. Ratio = 0.731/0.25 = 2.924. V-belt has nearly 3× the effective friction of flat belt."),
P("V-belt: groove angle 2β=38°, μ=0.2, effective μ'=μ/sinβ. Find μ'.", "μ' = 0.614", "β = 19°, sin19° = 0.3256", "μ' = 0.2/sin19° = 0.2/0.3256 = 0.614. The wedging action gives the V-belt much higher effective friction than a flat belt."),
P("Chain drive: pitch p=15.875 mm, number of teeth z₁=20, z₂=60. Find speed ratio.", "Speed ratio = 3", "Speed ratio = z₂/z₁ = N₁/N₂", "Speed ratio = 60/20 = 3. Maximum recommended speed ratio for chain is 7:1. Chordal action limits maximum speed."),
P("Chain pitch p=12.7 mm, z=20 teeth on sprocket. Find the pitch circle diameter.", "d ≈ 81.2 mm", "d = p/sin(180°/z)", "d = 12.7/sin(180/20 = 9°) = 12.7/sin9° = 12.7/0.1564 = 81.2 mm. Chordal action makes instantaneous chain speed vary within each pitch."),
P("Two spur gears: N₁=1200 rpm, z₁=20 teeth, z₂=60 teeth. Find output speed.", "N₂ = 400 rpm", "N₁/N₂ = z₂/z₁", "1200/N₂ = 60/20 = 3. N₂ = 1200/3 = 400 rpm."),
P("Gear module m=4, z=30 teeth. Find pitch circle diameter.", "d = 120 mm", "d = m×z", "d = 4×30 = 120 mm. Addendum = m = 4 mm (standard), dedendum = 1.25m = 5 mm."),
P("A gear pair has module 3 mm and 20 and 60 teeth, centre distance?", "C = 120 mm", "C = m(z₁+z₂)/2", "C = 3×(20+60)/2 = 3×80/2 = 120 mm."),
P("Spur gear: module m=5, z=40. Find addendum, dedendum, and clearance.", "Addendum = 5 mm, dedendum = 6.25 mm, clearance = 1.25 mm", "Standard full-depth involute: a=m, d=1.25m, c=0.25m", "Addendum = m = 5. Dedendum = 1.25×5 = 6.25. Clearance = 6.25−5 = 1.25 mm."),
P("Gear teeth transmit tangential force Ft=2000 N at pressure angle φ=20°. Find radial force.", "Fr = 728 N", "Fr = Ft×tanφ", "tan20°=0.364. Fr = 2000×0.364 = 728 N."),
P("Compound gear train: A(20T) drives B(60T) on same shaft as C(25T) driving D(75T). Find overall velocity ratio.", "VR = 9", "VR = (z_B/z_A)×(z_D/z_C)", "VR = (60/20)×(75/25) = 3×3 = 9. Driver speed = 9× driven speed."),
P("Compound train: input 500 rpm with A(25T)→B(100T)→C(30T)→D(90T). Find output speed.", "N_out ≈ 41.7 rpm", "VR = (100/25)×(90/30) = 4×3 = 12; N_out = 500/12", "VR = 4×3=12. N_out = 500/12 = 41.67 rpm."),
P("Reverted gear train: reverted condition requires input and output shafts coaxial. Find the condition on tooth sums.", "z₁+z₂ = z₃+z₄", "Reverted: same input/output shaft → centre distance equality", "For coaxial reversion, centre distances equal: m₁(z₁+z₂)/2 = m₃(z₃+z₄)/2. For same module: z₁+z₂ = z₃+z₄."),
P("Epicyclic gear: arm speed +100 rpm, sun gear 80 rpm CCW. Sun z=20, planet z=40, ring z=100. Find ring speed.", "N_ring = 104 rpm", "Tabulation: relative to arm, sun speed = Ns−Na; (Ns−Na)×z_s = −(Nr−Na)×z_r", "Relative to arm: sun = 80−100 = −20 rpm. Meshing: (Ns−Na)×z_s = −(Nr−Na)×z_r. −20×20 = −(Nr−100)×100 → −400 = −100(Nr−100) → Nr−100 = 4 → Nr = 104 rpm. Ring tooth count must be z_r = z_s + 2z_p = 20+80 = 100."),
P("Epicyclic train tabulation: arm +10 rpm, sun A(30T) drives planet B(50T) meshing ring C. Relative to the arm the sun is at −20 rpm (arm fixed, sun −20 rpm). Find ring speed.", "N_C = 16.92 rpm", "Tabulate: sun rel arm = Ns−Na = −30; (Ns−Na)×z_s = −(N_C−Na)×z_C; z_C = z_s+2z_p = 130", "Sun relative to arm = −20−10 = −30 rpm. Ring teeth z_C = 30+2×50 = 130. −30×30 = −(N_C−10)×130 → −900 = −130(N_C−10) → N_C−10 = 6.92 → N_C = 16.92 rpm absolute."),
P("Minimum teeth on pinion for no interference: φ=20° full depth (k=1). Find z_min.", "z_min = 17.1 → 18 teeth", "z_min = 2k/sin²φ", "sin20°=0.342, sin²φ=0.11698. z_min = 2×1/0.11698 = 17.1. Take 18. Or 1×2/0.1169 = 17.09 → 18."),
P("Minimum teeth on pinion for φ=14.5° (k=1).", "z_min = 32", "z_min = 2k/sin²φ", "sin14.5°=0.2504, sin²φ=0.0627. z_min = 2/0.0627 = 31.9 ≈ 32."),
P("Pressure angle φ=25°, find z_min for no interference.", "z_min = 11.2 → 12", "z_min = 2k/sin²φ", "sin25°=0.4226, sin²φ=0.1786. z_min = 2/0.1786 = 11.2 ≈ 12. Higher pressure angle permits fewer teeth without interference."),
P("Single plate clutch: uniform wear, R₁=100 mm, R₂=60 mm, μ=0.3, p=0.2 MPa. Find torque.", "T = 1206 N·m", "T = πμp(R₁²−R₂²)", "p=0.2 MPa = 2×10⁵ Pa. T = π×0.3×2×10⁵×(0.1²−0.06²) = 188495×(0.01−0.0036) = 188495×0.0064 = 1206 N·m."),
P("Multi-plate clutch: 4 pairs of friction surfaces, uniform wear R₁=80 mm, R₂=50 mm, μ=0.25, p=150 kPa. Find T.", "T = 1838 N·m", "T = n×πμp(R₁²−R₂²)", "n=4. R₁²−R₂²=0.0064−0.0025=0.0039. T = 4×π×0.25×150000×0.0039 = 4×π×146.25 = 4×459.5 = 1838 N·m. Each friction face pair adds equal torque."),
P("Uniform pressure plate clutch: R₁=120 mm, R₂=80 mm, μ=0.3, p=200 kPa. Find T for single pair.", "T = 152.8 N·m", "T = ⅔πμp(R₁³−R₂³)", "R₁³=0.001728, R₂³=0.000512, difference=0.001216. T = ⅔×π×0.3×200000×0.001216 = ⅔×π×72.96 = 152.8 N·m. Uniform pressure gives slightly different result than uniform wear."),
P("Cone clutch: mean radius 100 mm, semi-cone angle α=12.5°, μ=0.3, axial force W=500 N. Find torque.", "T = 69.3 N·m", "T = μWR/sinα", "sin12.5°=0.2164. T = 0.3×500×0.1/0.2164 = 15/0.2164 = 69.3 N·m."),
P("Cone clutch: compare torque with same W,R,μ but α=10° vs 20°.", "T(10°)/T(20°) = 1.97", "T = μWR/sinα", "sin10°=0.1736, sin20°=0.342. T ratio = 0.342/0.1736 = 1.97. Smaller semi-cone angle gives ~2× torque but more wear and possible sticking."),
P("Band brake: ratio T₁/T₂=e^μθ, μ=0.35, θ=270°. Find ratio.", "T₁/T₂ ≈ 5.20", "θ=270° = 4.712 rad", "μθ = 0.35×4.712 = 1.649. T₁/T₂ = e^1.649 = 5.20. The tight side carries 5.2 times the slack side tension."),
P("Band brake with drum 400 mm and lever, T₁=8000 N, T₂=1600 N. Net torque capacity?", "T = 1280 N·m", "Net T = (T₁−T₂)×r", "T₁−T₂ = 6400 N. r=0.2 m. T = 6400×0.2 = 1280 N·m."),
P("Block brake: lever 300 mm, drum radius 150 mm, hinge placed so friction helps apply the block. When is the brake self-locking?", "When friction moment about the hinge alone is enough to brake, applied force → 0", "Self-locking: friction force induces its own normal force, closing the loop", "If the hinge is placed so the friction force creates a moment about the hinge that adds to the applied force, self-locking occurs. Then the applied effort can be zero: P = 0, and the brake holds by its own friction."),
P("Internal expanding brake: shoe pressure p. Commonly assumed p ∝ sinθ. If p_max=1 MPa at θ=90°, find p at θ=30°.", "p = 0.5 MPa", "For internal shoe: p = p_max×sinθ/sinθ_max", "sin30°=0.5, sin90°=1. p = 1×0.5/1 = 0.5 MPa."),
P("Cam: follower with SHM, lift h=40 mm, return stroke 180°→360° at cam speed N=300 rpm. Find follower velocity at θ=270° during return.", "v = 0.628 m/s", "SHM: y=(h/2)(1+cosθ) on return; v=(h/2)ω sinθ; max at mid-travel", "ω = 2π×300/60 = 31.42 rad/s. Middle of return (θ=270°) is the SHM midpoint: v = (h/2)ω×sin(return-position). At midpoint: v = 0.02×31.42 = 0.628 m/s (peak return velocity hω/2)."),
P("Cam speed ω=20 rad/s, cycloidal motion lift 50 mm. Find max follower acceleration during the lift occupying 90° of cam rotation.", "a_max = 50.9 m/s²", "Cycloidal: a_max = 2πω²h/φ² where φ in rad", "φ = 90° = π/2 rad → φ² = 2.467. a_max = 2π×400×0.05/2.467 = 125.66/2.467 = 50.9 m/s². Finitely bounded, unlike constant velocity which has infinite spikes."),
P("Constant velocity cam: follower lift 50 mm at constant speed v=1.2 m/s, cam ω=10 rad/s. Find rise time and cam angle for the rise.", "t = 0.0417 s, rise angle φ = 23.9°", "t = h/v; φ = ω×t", "t = 0.05/1.2 = 0.04167 s. φ = 10×0.04167 = 0.4167 rad = 23.9°. Constant velocity produces infinite acceleration at start and end (jerk)."),
P("Constant acceleration-retardation cam: follower receives uniform acceleration a=40 m/s² for 0.1 s. Find velocity attained and distance covered.", "v = 4 m/s, s = 0.2 m", "v = at; s = ½at²", "v = 40×0.1 = 4 m/s. s = ½×40×0.1² = 0.2 m."),
P("Jump of follower: cam ω=10 rad/s, spring stiffness k=2 kN/m, follower mass m=0.5 kg. Follower needs max acceleration a=60 m/s². Find minimum spring preload to avoid jump.", "F ≥ 30 N", "No jump: F_spring ≥ m×a", "F ≥ m×a = 0.5×60 = 30 N required at the fold-over point. Actual spring force = k×deflection + preload; jump occurs when spring force drops below m×a."),
P("Watt governor: height h at speed N=60 rpm.", "h = 248 mm", "Watt: h = 895/N² (m)", "h = 895/60² = 895/3600 = 0.2486 m = 248.6 mm."),
P("Porter governor: h = 895/N²×(1+m/2M)... if m=4 kg, M=8 kg. Compare with Watt at same N.", "Porter h is 1.25× Watt h", "Porter: h = 895/N²×(1+m/2M)", "For Porter: factor = (1+m/2M) = 1+4/16 = 1.25 (approximately h = (1+m/2M)... Using standard: h = 895/N² × (1+m/2M) for given geometry — this shows Porter height is 25% larger than Watt at same speed for this mass ratio."),
P("Porter governor formula: h = 895/N² × (1+m/2M). At N=120 rpm, m=4 kg, M=8 kg.", "h = 0.0777 m (77.7 mm)", "h = (895/120²)×(1+4/(2×8))", "895/14400 = 0.06215. Factor = 1+4/16 = 1.25. h = 0.06215×1.25 = 0.0777 m = 77.7 mm."),
P("Hartnell governor: find equilibrium speed when spring force = 600 N at 1:1 lever ratio, mass = 4 kg, radius of rotation r=0.1 m.", "N = 370 rpm", "F_c = mrω² = 600; ω² = 600/(4×0.1) = 1500", "ω² = 600/0.4 = 1500. ω = √1500 = 38.73 rad/s. N = 60ω/2π = 38.73×60/6.283 = 370 rpm."),
P("Proell governor, sensitivity: find sensitivity at N₁=100 rpm, N₂=120 rpm.", "S = 0.1818", "Sensitivity = (N₂−N₁)/N_mean = 2(N₂−N₁)/(N₂+N₁)", "N_mean = 110. S = 2(120−100)/(220) = 40/220 = 0.1818 = 18.18%."),
P("Isochronism: define condition for an isochronous governor.", "Equilibrium speed constant for all radii → speed range = 0", "Isochronous: N₁ = N₂, sensitivity → ∞", "An isochronous governor maintains constant speed regardless of sleeve position, i.e., the equilibrium speed is same at all radii of rotation. Sensitivity = 2(N₂−N₁)/(N₂+N₁) → 0/∞ → the governor has infinite sensitivity. Rare in practice."),
P("Flywheel: mean speed 300 rpm, coefficient of fluctuation of speed k=0.04, fluctuation of energy E=2500 J. Find moment of inertia.", "I = 63.3 kg·m²", "E = Iω²k; ω = 2π×300/60 = 31.42 rad/s", "ω² = 987. E = Iω²k → I = E/(ω²k) = 2500/(987×0.04) = 2500/39.48 = 63.3 kg·m²."),
P("Flywheel mean speed ω=40 rad/s, k=0.05, I=2 kg·m². Find fluctuation of energy.", "E = 160 J", "E = Iω²k", "E = 2×1600×0.05 = 160 J."),
P("Punching press: hole 20 mm in 15 mm thick plate, shear strength 300 MPa, 120 strokes/min. Find power required.", "P = 4240 W (4.24 kW)", "Work/stroke = ½×πdtτ×t; Power = work×strokes/s", "Max shear force = π×0.02×0.015×300×10⁶ = 282.7 kN. Energy per stroke = ½×F×thickness = ½×282700×0.015 = 2120 J. 120 strokes/min = 2/s → P = 2120×2 = 4240 W."),
P("Turning moment diagram of 4-stroke engine: area of +ve loop 2000 mm² (scale 100 J/mm²). Find energy fluctuation per cycle of 720°.", "E = 200 kJ for single cylinder cyclic fluctuation", "For 4-stroke, energy fluctuation = positive loop area above mean", "Mean torque line divides the loop so that fluctuation = total area above mean torque = 2000×100 = 200000 J = 200 kJ for the 720° cycle."),
P("Crankshaft: reciprocating mass m=4 kg, crank r=60 mm, ω=30 rad/s at θ=90°. Find primary force magnitude.", "F_p = 0 at θ=90° (max = mrω² = 216 N at θ=0°)", "F_primary = m r ω² cosθ", "m r ω² = 4×0.06×900 = 216 N. At θ=90°: cos90°=0 → F_primary = 0. Maximum 216 N occurs at TDC, θ=0°."),
P("Primary force at θ=0° for m=5 kg, r=0.1 m, ω=20 rad/s.", "F_p = 200 N", "F_p = mrω²", "mrω² = 5×0.1×20² = 0.5×400 = 200 N."),
P("Secondary unbalanced force: n=l/r=4, compare max primary and secondary for same m,r,ω.", "F_s,max = F_p,max/4", "F_secondary = (mrω²cos2θ)/n", "Secondary max = mrω²/n. With n=4: F_s,max = mrω²/4 = 0.25×F_p,max. Secondary swings at twice the crank speed."),
P("Locomotive: crank r=0.3 m, reciprocating mass 200 kg per cylinder, ω=10 rad/s. Hammer blow for a 2-cylinder location with cranks at 90°?", "Hammer blow peak ≈ 8485 N", "Hammer blow = mrω² per cylinder; two cylinders → √2×mrω²", "mrω² = 200×0.3×100 = 6000 N per cylinder. Two cylinders with 90° cranks give resultant vertical hammer blow = mrω²√2 = 6000×1.414 = 8485 N (maximum of the slowly varying resultant)."),
P("Balancing: static and dynamic. A rotor has two masses. When is dynamic balancing required?", "When unbalanced couples exist even if resultant force is zero", "Static balance: ∑F=0. Dynamic: also ∑Couple=0", "Static balance alone ensures resultant force passes through the axis; but two equal opposite forces at different planes produce a couple requiring dynamic balancing."),
P("Gyroscope: disk I=0.5 kg·m², spin ω=40 rad/s, precession ωp=2 rad/s. Find gyroscopic couple.", "C = 40 N·m", "C = Iωωp", "C = 0.5×40×2 = 40 N·m. Direction: perpendicular to both spin and precession axes."),
P("Ship turning: rotor spin axis along length, ship turns left. Find the gyroscopic couple effect on bow/stern.", "Bow rises, stern dips", "Reacting couple on ship: depends on spin direction; for CW spin seen from stern, left turn raises bow", "With the rotor spinning clockwise viewed from the stern and the ship turning to port (left), the active gyroscopic couple tends to raise the bow and depress the stern. If the spin were reversed, bow dips and stern rises."),
P("Gyroscope precession: I=2 kg·m², ω=30 rad/s, couple 60 N·m. Find precession velocity.", "ωp = 1 rad/s", "C = Iωωp", "ωp = C/(Iω) = 60/(2×30) = 1 rad/s."),
P("Spring-mass: m=2 kg, k=800 N/m. Find natural frequency.", "fn = 3.18 Hz", "fn = ½π√(k/m)", "√(k/m) = √(800/2) = √400 = 20. fn = 20/2π = 3.18 Hz. ωn = 20 rad/s."),
P("Damped system: m=5 kg, k=2000 N/m, c=50 N·s/m. Find damping ratio ζ.", "ζ = 0.25", "ζ = c/cc, cc = 2√(km)", "cc = 2√(2000×5) = 2×100 = 200. ζ = 50/200 = 0.25."),
P("Critical damping coefficient for m=2 kg, k=1800 N/m.", "cc = 120 N·s/m", "cc = 2√(km)", "cc = 2√(1800×2) = 2×60 = 120 N·s/m."),
P("Damped natural frequency: ωn=20 rad/s, ζ=0.25.", "ωd = 19.36 rad/s", "ωd = ωn√(1−ζ²)", "ωd = 20×√(1−0.0625) = 20×0.9682 = 19.36 rad/s."),
P("Logarithmic decrement δ from two successive amplitudes 10 mm and 6 mm.", "δ = 0.511", "δ = ln(x₁/x₂)", "δ = ln(10/6) = ln(1.667) = 0.511. Damping ratio ζ = δ/√(4π²+δ²) = 0.081."),
P("Whirling of shaft: EI of shaft, mass m at centre, length l. Critical speed formula for simply supported shaft with central disc?", "ωc = π²√(EI/(ml³))", "ωc = (π²/l²)√(EI/m) for simply supported mid-span", "For simply supported shaft, central load deflection δ = mgL³/48EI, but higher-mode formula: ωc = (n²π²/l²)√(EI/m) with fundamental n=1: ωc = (π²/l²)√(EI/m). Critical speed Nc = 60ωc/2π rpm."),
P("Cantilever shaft with tip mass m, length l, EI. Find fundamental natural frequency of a cantilever beam with end mass.", "ωn = √(3EI/(ml³))", "End-mass cantilever: k = 3EI/l³", "k = 3EI/l³. ωn = √(k/m) = √(3EI/(ml³))." ),
P("Simple pendulum: length l=1 m. Find natural frequency.", "fn = 0.498 Hz", "fn = ½π√(g/l)", "fn = (1/2π)√(9.81/1) = (1/6.283)×3.132 = 0.498 Hz. T=2.01 s."),
P("Forced vibration: m=1 kg, k=400 N/m, ωn=20 rad/s, F₀=10 N, exciting frequency ω=10 rad/s (no damping). Find amplitude.", "X = 1.333 mm", "X = (F₀/k)/(1−r²), r=ω/ωn", "F₀/k = 10/400 = 0.025 m. r = 10/20 = 0.5. r²=0.25. X = 0.025/(1−0.25) = 0.025/0.75 = 0.0333 m = 33.3 mm."),
P("Resonance condition in forced vibration: ωn=ω. What is amplitude for undamped system?", "Infinite (theoretically)", "X = (F₀/k)/(1−r²); at r=1 → ∞", "At resonance r=1, denominator →0, amplitude →∞ for zero damping. In practice finite due to damping."),
P("Transmissibility: r=3, ζ=0. What is transmissibility ratio TR?", "TR = 0.125", "TR = 1/(1−r²) for ζ=0", "TR = 1/(1−9) = 1/(−8) → |TR| = 0.125. Magnitude 0.125 (isolated vibration reduced to 12.5%)."),
P("Isolation efficiency at r=√2 (ζ=0).", "Efficiency = 100% (TR = 1, no isolation effect boundary)", "At r=√2, TR=1 for zero damping", "TR = 1/(1−r²) = 1/(1−2) = −1 → |TR|=1. Beyond r=√2 isolation improves. Efficiency = (1−TR)×100. At r=3: efficiency = 87.5%."),
P("Longitudinal vibration of rod: E=200 GPa, ρ=7800 kg/m³, rod length 1 m fixed-free. Find fundamental frequency.", "fn = 1266 Hz", "fn = (1/4l)√(E/ρ) for fixed-free", "√(E/ρ) = √(200×10⁹/7800) = √(2.564×10⁷) = 5063 m/s. Fixed-free: fn = c/(4l) = 5063/(4×1) = 1265.9 Hz."),
P("Torsional vibration of two disks on shaft: polar MOI J=πd⁴/32 shaft. G=80 GPa, d=50 mm, l=1 m. Find torsional stiffness k_t.", "k_t = 49088 N·m/rad", "k_t = GJ/l", "J = π×(0.05)⁴/32 = π×6.25×10⁻⁶/32 = 6.136×10⁻⁷ m⁴. k_t = GJ/l = 80×10⁹×6.136×10⁻⁷/1 = 49088 N·m/rad."),
P("Vibration isolation: motor 20 kg, 4 mounts each k=500 N/m. Find natural frequency in Hz.", "fn = 1.59 Hz", "Total k = 4×500 = 2000; fn = (1/2π)√(k/m)", "k=2000 N/m. √(2000/20) = √100 = 10. fn = 10/6.283 = 1.59 Hz."),
P("Critical speed of shaft: simply supported, l=0.5 m, EI=2×10⁴ N·m², mass m=5 kg central. Find ωc.", "ωc = 2497 rad/s", "ωc = (π²/l²)√(EI/m)", "EI/m = 20000/5 = 4000, √4000 = 63.25. ωc = (9.8696/0.25)×63.25 = 39.48×63.25 = 2497 rad/s. Nc = 2497×60/2π = 23840 rpm."),
P("Grashof link with s=2, l=7, p=4, q=6: which link is the crank (if Grashof satisfied)?", "Shortest link (s=2 cm) can rotate fully", "Grashof: s+l < p+q; shortest link or its neighbour is crank", "s+l = 2+7 = 9, p+q = 4+6 = 10. 9<10 ✓ Grashof. The shortest link is the crank and can revolve full 360°."),
P("Kennedy theorem: number of instant centres for n=6 links.", "IC = 15", "N = n(n−1)/2", "N = 6×5/2 = 15 instant centres."),
P("Slider-crank: r=3 cm, crank θ=90°, ω=12 rad/s, n=l/r=3. Find piston velocity at θ=90°.", "v = 0.36 m/s", "At θ=90°: sinθ=1, sin2θ=0 → v=ωr", "v = ωr(sinθ + sin2θ/2n) = ωr(1 + 0) = 12×0.03 = 0.36 m/s."),
P("Slider-crank piston velocity maximum: n=l/r=4. Find the crank angle θ for v_max.", "θ ≈ 77° (cosθ = 0.2247)", "dv/dθ=0 → cosθ + cos2θ/n = 0 → 2cos²θ + ncosθ − 1 = 0", "Set dv/dθ = ωr(cosθ + cos2θ/n) = 0 → 2cos²θ + ncosθ − 1 = 0 → cosθ = (√(n²+8)−n)/4. For n=4: cosθ = (√24−4)/4 = (4.899−4)/4 = 0.2247 → θ = 77°."),
P("Gruebler criterion: 7 links, 9 lower pairs, 0 higher pairs. DOF?", "DOF = 0 (structure)", "DOF = 3(n−1)−2j₁−j₂", "DOF = 3(7−1)−2×9−0 = 18−18 = 0. A statically determinate truss-like chain — no motion."),
P("Cam and follower: n=3 links, j₁=2 lower pairs, j₂=1 higher pair. Kutzbach DOF?", "DOF = 1", "DOF = 3(n−1)−2j₁−j₂", "DOF = 3(3−1)−2(2)−1 = 6−4−1 = 1. The cam input gives one DOF as expected."),
P("Pantograph contains how many links and DOF?", "4-bar pantograph: DOF = 1", "Kutzbach with n=4, j₁=4", "DOF = 3(4−1)−2(4) = 9−8 = 1."),
P("Peaucellier mechanism has 8 links. Find DOF by Kutzbach.", "DOF = 1", "n=8, j₁=10 (6 pins+...): DOF = 3(7)−20 = 1", "DOF = 3(8−1)−2(10) = 21−20 = 1. Exact straight-line linkage."),
P("Oldham coupling: velocity ratio between shafts is always?", "1:1 (constant)", "Oldham has same speed both shafts", "Two offset parallel shafts connected by Oldham coupling rotate at identical speeds (1:1) regardless of offset because sliding intermediation preserves angular velocity."),
P("Ackermann steering: wheelbase l=2.5 m, track width b=1.4 m, outer wheel angle 40°. Find inner wheel angle for correct steering condition.", "Inner angle ≈ 29.7°", "cot(inner) − cot(outer) = b/l", "cot(outer) = cot40° = 1.192. b/l = 1.4/2.5 = 0.56. cot(inner) = 1.192 + 0.56 = 1.752 → inner = 29.7°. The inner wheel must always turn through the larger angle."),
P("Four-bar coupler curve: how many distinct instant centres in a 4-bar?", "6 instant centres", "N = n(n−1)/2 = 4×3/2", "N = 4×3/2 = 6 instant centres. Kennedy theorem: any three of the four links have their three instant centres collinear."),
P("Quick return mechanism: QR=1.5. Find forward and return stroke times if total cycle time 5 s.", "Time_forward = 3 s, Time_return = 2 s", "Forward = [QR/(QR+1)]×T_cycle", "T_f = 1.5/(1.5+1)×5 = (1.5/2.5)×5 = 3 s. T_r = 5−3 = 2 s."),
P("Shaper with stroke 300 mm, cutting speed 20 m/min, QR=2. Find cutting and return time per stroke.", "t_cutting = 0.9 s, return = 0.45 s", "v_cut = stroke/t_cut; return time = t_cut/QR", "Cutting time = 0.3/(20/60) = 0.3×3 = 0.9 s. Return time = 0.9/2 = 0.45 s. Total stroke time = 1.35 s."),
P("D'Alembert principle relates inertia force to which quantity in mechanism analysis?", "Applied force balance: F_applied + F_inertia = 0 (dynamic equilibrium)", "Inertia force = −m·a", "D'Alembert: treat dynamic problem as static equilibrium by adding inertia force −ma. Used in force analysis of links."),
P("Four-bar: driving crank 100 mm at 60 rad/s. Find velocity of a point at r=100 mm perpendicular (pure rotation).", "v = 6 m/s", "v = ωr for pure rotation", "v = 60×0.1 = 6 m/s. Direction tangent to the crankshaft circle."),
];
SSC_JE_ENC2_TOMFLUIDS.fluids = [
P("A mercury manometer shows 200 mm height (ρ_Hg = 13600 kg/m³, g=9.81). Find the gauge pressure.", "p = 26.7 kPa", "p = ρgh", "p = 13600×9.81×0.2 = 26683 Pa = 26.68 kPa. Mercury is 13.6× denser than water, so 200 mm Hg ≈ 2.72 m of water."),
P("Differential manometer connects two water pipes; mercury level difference is 150 mm. Find differential pressure.", "Δp = 18.5 kPa", "Δp = (ρ_m − ρ_w)gh", "Δp = (13600 − 1000)×9.81×0.15 = 12600×9.81×0.15 = 18541 Pa = 18.5 kPa. The water legs cancel; only the density difference counts."),
P("A water column is 5 m high. Find the gauge pressure at its base (ρ=1000 kg/m³).", "p = 49.05 kPa", "p = ρgh, γ = 9810 N/m³", "p = 9810×5 = 49050 Pa = 49.05 kPa. Every 10.33 m of water gives ~1 atm."),
P("An inclined manometer reads 200 mm along a tube inclined at 30°. Find the vertical head and pressure (water).", "h = 100 mm, p = 981 Pa", "h = L×sinθ", "h = 0.2×sin30° = 0.1 m = 100 mm H₂O. p = 9810×0.1 = 981 Pa. Inclined tubes magnify the reading for small pressures."),
P("Vertical submerged gate 3 m wide × 2 m high, top edge at the free surface. Find total hydrostatic force.", "F = 88.3 kN", "F = γh̄A, h̄ = depth of centroid = 1 m", "A = 3×2 = 6 m², h̄ = 1 m (centroid at mid-height). F = 9810×1×6 = 58860 N = 58.9 kN. For full-depth rectangle h̄ = h/2 = 1 m."),
P("Vertical rectangular gate 2 m wide × 3 m high, centroid 1.5 m below surface. Find depth of centre of pressure hp.", "hp = 2.0 m", "hp = h̄ + I_G/(A·h̄), I_G = bh³/12", "A = 2×3 = 6 m², I_G = 2×27/12 = 4.5 m⁴. hp = 1.5 + 4.5/(6×1.5) = 1.5 + 0.5 = 2.0 m. hp is always below the centroid."),
P("Rectangular gate 2 m × 1.5 m inclined 45°, centroid at depth 4 m. Find normal hydrostatic force.", "F = 117.7 kN", "F = γh̄A (normal to plate)", "A = 2×1.5 = 3 m². F = 9810×4×3 = 117720 N = 117.7 kN. F depends on centroid depth, not plate orientation."),
P("Vertical gate 3 m wide, 2 m high, hinged at bottom, water 2 m on one side. Find the horizontal force needed at the top edge.", "P = 19.6 kN", "Resultant at h/3 above base; moment: P×h = F×(h/3)", "F = 9810×(2/2)×(3×2) = 9810×6 = 58860 N. Resultant at 2/3 from top → 0.667 m above hinge. P = F×(0.667/2) = 58860×0.3333 = 19620 N = 19.6 kN."),
P("Curved quadrant gate radius 2 m, width 2 m, water flush with top. Find resultant hydrostatic force on the gate.", "F ≈ 73.1 kN", "F_H = γh̄A_v; F_V = γ×volume of water above; F = √(F_H²+F_V²)", "F_H = γ×(R/2)×(R×b) = 9810×1×4 = 39240 N. F_V = γ×(πR²/4)×b = 9810×π×2 = 61638 N. F = √(39240²+61638²) = 73068 N ≈ 73.1 kN."),
P("A 0.4 m cube floats with 0.15 m submerged in water. Find its weight.", "W = 235 N", "W = buoyant force = γ×V_submerged", "V_sub = 0.4×0.4×0.15 = 0.024 m³. W = 9810×0.024 = 235.4 N. Density of block = 235.4/(0.064×9.81) = 375 kg/m³."),
P("Pontoon 6 m × 3 m × 1 m draft. Its centre of gravity G is 0.6 m above centre of buoyancy B. Find metacentric height GM.", "GM = 0.15 m (stable)", "GM = BM − BG, BM = I/V, I = Lb³/12", "I = 6×27/12 = 13.5 m⁴. V = 6×3×1 = 18 m³. BM = 13.5/18 = 0.75 m. GM = 0.75 − 0.6 = 0.15 m > 0 → stable."),
P("Stability experiment: a 50 N weight moves 0.2 m across a pontoon of displacement 40000 N; attached pendulum (1 m) deflects 20 mm. Find GM.", "GM = 12.5 mm", "GM = (w×d)/(W×tanθ); tanθ = deflection/1", "tanθ = 0.02/1 = 0.02. GM = (50×0.2)/(40000×0.02) = 10/800 = 0.0125 m = 12.5 mm. This is the experimental metacentric height."),
P("Rectangular pontoon 6 m long, 3 m wide floats 1 m deep. Find BM (distance of metacentre above buoyancy centre).", "BM = 0.75 m", "BM = I/V, I = Lb³/12 about longitudinal axis", "I = 6×3³/12 = 13.5 m⁴. V = 6×3×1 = 18 m³. BM = 13.5/18 = 0.75 m. Larger BM means more stable (along the length, floats rock side-to-side)."),
P("Open vertical cylinder radius 0.3 m rotates at ω=20 rad/s. Find the rise of liquid at the wall due to the paraboloid.", "Rise = 1.84 m", "h = ω²r²/2g", "h = 400×0.09/(2×9.81) = 36/19.62 = 1.835 m. The free surface is a paraboloid; volume of air equals volume of liquid above original level."),
P("Open tank accelerates horizontally at a=2 m/s². Find the slope angle of the free surface.", "θ = 11.5°", "tanθ = a/g", "tanθ = 2/9.81 = 0.2039 → θ = 11.53°. Surface remains a plane at this angle; liquid pile-up occurs at the rear."),
P("Cylinder radius 0.5 m originally filled with liquid to depth 0.6 m. At what angular speed does the centre of the base just become dry?", "ω = 9.70 rad/s", "For dry centre: ω²R²/2g = 2H", "Paraboloid vertex reaches base: (ω²R²/2g) − (ω²R²/2g)×0 = 2H → ω²R²/2g = 2×... using volume: ω² = 4gH/R² = 4×9.81×0.6/0.25 = 94.18 → ω = 9.70 rad/s."),
P("Pipe reduces from 300 mm to 150 mm. Velocity in large section is 2 m/s. Find velocity in small section.", "V₂ = 8 m/s", "A₁V₁ = A₂V₂", "V₂ = V₁×(D₁/D₂)² = 2×(300/150)² = 2×4 = 8 m/s. Velocity rises ~ the square of the diameter ratio."),
P("Venturimeter: d₁=200 mm, d₂=100 mm, Δh=0.25 m water, Cd=0.98. Find discharge.", "Q ≈ 0.0176 m³/s", "Q = Cd×A₁A₂/√(A₁²−A₂²)×√(2gΔh)", "A₁=0.0314, A₂=0.00785 m². √(2gΔh)=2.215 m/s. Q_ideal = (2.467e-4/0.03042)×2.215 = 0.01796 m³/s. Q = 0.98×0.01796 = 0.0176 m³/s."),
P("Pitot tube in water registers 50 mm of mercury differential. Find flow velocity.", "v = 3.65 m/s", "Δh_water = Δh_Hg×13.6; v = √(2gΔh)", "Δh = 0.05×13.6 = 0.68 m water. v = √(2×9.81×0.68) = √13.34 = 3.65 m/s. Pitot reads stagnation minus static head."),
P("Orifice of area 0.001 m² under 2 m head, Cd=0.62. Find discharge.", "Q = 0.00388 m³/s", "Q = Cd·A·√(2gH)", "√(2gH) = √(19.62×2) = √39.24 = 6.264 m/s. Q = 0.62×0.001×6.264 = 0.00388 m³/s."),
P("Orifice under head 2 m with Cv=0.98. Find actual jet velocity.", "v_actual = 6.14 m/s", "v = Cv×√(2gH)", "v_theory = √(2×9.81×2) = 6.264 m/s. v_actual = 0.98×6.264 = 6.14 m/s. Cv accounts for friction in the orifice."),
P("Orifice with Cc=0.62 and Cv=0.98. Find the coefficient of discharge Cd.", "Cd = 0.608", "Cd = Cc×Cv", "Cd = 0.62×0.98 = 0.6076 ≈ 0.608. The product of contraction and velocity coefficients."),
P("Rectangular notch: width L=1 m, head h=0.2 m, Cd=0.62. Find discharge.", "Q = 0.164 m³/s", "Q = (2/3)Cd√(2g)Lh^(3/2)", "h^1.5 = 0.2^1.5 = 0.08944. Q = 0.6667×0.62×4.429×1×0.08944 = 1.8305×0.08944 = 0.164 m³/s."),
P("90° triangular notch, head h=0.3 m, Cd=0.6. Find discharge.", "Q = 0.0699 m³/s", "Q = (8/15)Cd√(2g)tan(θ/2)h^(5/2)", "tan45°=1. h^2.5 = 0.3^2.5 = 0.0493. Q = 0.5333×0.6×4.429×1×0.0493 = 1.417×0.0493 = 0.0699 m³/s."),
P("Laminar flow: μ=0.001 Pa·s, d=20 mm, l=10 m, Δp=1000 Pa. Find discharge via Hagen–Poiseuille.", "Q = 3.93×10⁻⁴ m³/s", "Q = πΔp d⁴/(128μl)", "d⁴ = (0.02)⁴ = 1.6×10⁻⁷. Q = π×1000×1.6e-7/(128×0.001×10) = 5.027e-4/1.28 = 3.93×10⁻⁴ m³/s. Average velocity = Q/A = 1.25 m/s."),
P("Laminar flow in 10 mm pipe, v=1 m/s, l=5 m, μ=0.001 Pa·s. Find pressure drop.", "Δp = 1.6 kPa", "Δp = 32μvl/d²", "Δp = 32×0.001×1×5/(0.01)² = 0.16/1e-4 = 1600 Pa = 1.6 kPa. Hagen–Poiseuille: Δp ∝ v/d² for laminar flow."),
P("Water flows at 2 m/s in a 50 mm pipe. Find Reynolds number (μ=0.001 Pa·s).", "Re = 100000 (turbulent)", "Re = ρvD/μ", "Re = 1000×2×0.05/0.001 = 100000. Critical Re for pipe flow ≈ 2300; 100000 is fully turbulent."),
P("Air at 20°C (ρ=1.2, μ=1.8×10⁻⁵) flows 10 m/s in 20 mm duct. Find Re.", "Re = 13333", "Re = ρvD/μ", "Re = 1.2×10×0.02/1.8×10⁻⁵ = 0.24/1.8×10⁻⁵ = 13333. Turbulent (above 2300)."),
P("Pipe flow: f=0.02, l=50 m, v=1.5 m/s, d=0.1 m. Find head loss by Darcy–Weisbach.", "h_f = 1.15 m", "h_f = f·l·v²/(2gd)", "h_f = 0.02×50×2.25/(2×9.81×0.1) = 2.25/1.962 = 1.147 m. In kPa: 0.047×... pressure loss = 9810×1.147 = 11.25 kPa."),
P("Minor loss: bend with K=0.9, velocity 2 m/s. Find head loss.", "h = 0.183 m", "h = K·v²/2g", "h = 0.9×4/19.62 = 0.1835 m. Equivalent length concept: same as a certain length of straight pipe."),
P("Sharp entrance to a pipe (K=0.5), velocity 2 m/s. Find head loss.", "h = 0.102 m", "h = K·v²/2g", "h = 0.5×4/19.62 = 0.1019 m. For a rounded entrance K ≈ 0.04 — much less."),
P("Sudden expansion: velocity drops from 2 m/s to 1 m/s. Find head loss.", "h = 0.051 m", "h = (v₁−v₂)²/2g", "h = (2−1)²/19.62 = 1/19.62 = 0.051 m. Loss depends on the velocity change, not the big/small area directly."),
P("Two parallel 100 mm pipes replace a single pipe of same length and friction factor. Find equivalent diameter.", "d_eq ≈ 0.132 m", "Same head loss: d_eq = d×n^(2/5)", "For n identical parallel pipes, Q_tot = nQ with same h_f: d_eq = d×n^(2/5) = 0.1×2^0.4 = 0.1×1.3195 = 0.132 m. Parallel pipes have reduced resistance."),
P("Siphon: pipe discharges from a reservoir, free drop 3 m, diameter 25 mm (losses neglected). Find velocity and discharge.", "v = 7.67 m/s, Q = 3.77×10⁻³ m³/s", "v = √(2gH); Q = vA", "v = √(2×9.81×3) = √58.86 = 7.67 m/s. A = π×0.0125² = 4.909×10⁻⁴ m². Q = 7.67×4.909e-4 = 3.77×10⁻³ m³/s."),
P("Siphon summit: water at 20°C, vapour head ≈ 0.24 m, barometric head 10.33 m. What is the practical max summit height above the reservoir?", "z_max ≈ 6–7 m (say 6.5 m)", "Summit pressure = p_atm − ρg(z+v²/2g+friction) > p_vapour", "p_atm − p_vapour ≈ 10.33−0.24 = 10.09 m of water. After deducting velocity head and friction, the practical maximum summit lift is about 6–7 m. Beyond this the siphon cavitates and breaks."),
P("Laminar boundary layer over flat plate at x=1 m, water v=1 m/s. Find thickness δ.", "δ = 5 mm", "δ = 5x/√Re_x; Re = vx/ν", "Re = 1×1/1e-6 = 10⁶. δ = 5×1/1000 = 0.005 m = 5 mm. Laminar plate BL grows like √x."),
P("Same conditions (x=1 m, Re=10⁶). Find displacement thickness δ*.", "δ* = 1.72 mm", "δ* = 1.72x/√Re_x", "δ* = 1.72×1/1000 = 0.00172 m = 1.72 mm. δ*/δ = 0.344 for laminar BL; for turbulent ≈ 1/8."),
P("Flat plate 1 m long, v=1 m/s water (Re=10⁶, laminar). Find drag coefficient CD.", "CD = 1.328×10⁻³", "CD = 1.328/√Re_L", "CD = 1.328/√(10⁶) = 1.328/1000 = 0.001328. Valid only when the whole plate BL is laminar (Re_L < 5×10⁵)."),
P("Plate 1 m × 1 m with CD=1.328×10⁻³, v=1 m/s water. Find drag force.", "F_D = 0.662 N", "F_D = ½ρv²ACD", "F_D = 0.5×1000×1×(1×1)×0.001328 = 0.664 N. Skin friction is small at low speed (form drag absent for a flat plate edge-on)."),
P("Sphere d=0.5 mm, density 2000 kg/m³ falling in water. Find Stokes terminal velocity.", "v_t = 0.136 m/s", "v_t = d²(ρ_s−ρ_f)g/(18μ)", "d² = 2.5×10⁻⁷ m². v_t = 2.5e-7×(2000−1000)×9.81/(18×0.001) = 2.4525e-3/0.018 = 0.136 m/s. Valid for Re < 1."),
P("Most economical rectangular channel with area 2 m². Find depth and width.", "y = 1 m, b = 2 m", "For most economical rectangle: b = 2y; A = b×y", "A = b×y = 2y² = 2 → y = 1 m, b = 2 m. Half the perimeter is the wetted perimeter optimised — least wetted perimeter for given area."),
P("Most economical trapezoidal channel: express hydraulic radius in terms of flow depth y.", "R = y/2", "Most economical trapezoid: sides at 60° (half hexagon), R = y/2", "For the most economical trapezoidal section (best hydraulic section, side slopes 60°), the hydraulic radius equals half the flow depth: R = y/2. Wetted perimeter is minimised for the given area."),
P("Hydraulic jump: upstream Froude number Fr₁=3. Find the conjugate depth ratio y₂/y₁.", "y₂/y₁ = 3.77", "y₂/y₁ = ½(√(1+8Fr₁²) − 1)", "y₂/y₁ = ½(√(1+8×9) − 1) = ½(√73 − 1) = ½(8.544 − 1) = 3.772. The jump always increases depth (for Fr₁>1)."),
P("Hydraulic jump with y₁=1 m, Fr₁=3. Find energy (head) loss in the jump.", "ΔE = 1.41 m", "ΔE = (y₂−y₁)³/(4y₁y₂)", "y₂ = 3.772 m. ΔE = (2.772)³/(4×1×3.772) = 21.30/15.09 = 1.41 m. Up to 50–70% of energy can be dissipated in a strong jump."),
P("Rectangular channel: n=0.015, R=0.5 m, S=0.001. Find velocity by Manning.", "v = 1.33 m/s", "v = (1/n)R^(2/3)S^(1/2)", "R^(2/3) = 0.5^(2/3) = 0.6299. S^(1/2) = 0.03162. v = 0.6299×0.03162/0.015 = 0.01992/0.015 = 1.33 m/s."),
P("What are the SI units of Manning roughness coefficient n?", "Dimensionally s·m⁻¹ᐟ³ (in practice treated as dimensionless)", "Check v = (1/n)R^(2/3)S^(1/2)", "v has m/s; R^(2/3) has m^(2/3); S is dimensionless. So n = R^(2/3)/v gives units s·m^(−1/3). Standard engineering tables quote n as a pure number (e.g. 0.015), ignoring dimensions."),
P("Rectangular channel: v=3 m/s, depth y=1 m. Find Froude number.", "Fr = 0.958 (subcritical)", "Fr = v/√(gy)", "√(9.81×1) = 3.132. Fr = 3/3.132 = 0.958 < 1 → subcritical (tranquil) flow. Critical state occurs at Fr = 1."),
P("What is the critical Froude number marking the transition between subcritical and supercritical flow?", "Fr = 1 (specific energy minimum)", "Fr = v/√(gy)", "At Fr = 1 the specific energy is a minimum and depth = critical depth. Fr < 1 slow/shallow-affected subcritical; Fr > 1 rapid supercritical flow."),
P("Compute Weber number: v=2 m/s, L=0.1 m, water ρ=1000, surface tension σ=0.073 N/m.", "We = 5479", "We = ρv²L/σ", "We = 1000×4×0.1/0.073 = 400/0.073 = 5479. We compares inertia to surface tension; large → surface tension negligible."),
P("Air at 15°C (c≈340 m/s) moving at 340 m/s. Find Mach number.", "M = 1 (sonic)", "M = v/c", "M = 340/340 = 1.0. Sonic flow — at this speed the local free-stream equals the speed of sound; choked conditions can follow."),
P("Froude-law model at linear scale 1:25. Find the velocity ratio.", "V_r = 1:5", "V_r = √L_r", "V_r = √(1/25) = 1/5. Gravitational similarity: Froude equal → velocities scale as the square root of the length scale."),
P("Same 1:25 model, same fluid. Find the discharge scale ratio.", "Q_r = 1:3125", "Q_r = V_r×A_r = L_r^(5/2)", "V_r = 1/5, A_r = (1/25)² = 1/625. Q_r = (1/5)×(1/625) = 1/3125 = L_r^2.5."),
P("Same model, same fluid. Find force (inertial) scale ratio.", "F_r = 1:15625", "F_r = L_r³ (mass ratio also L_r³)", "F ∝ ρL³(L/T²) → F_r = L_r³ = (1/25)³ = 1/15625. 15625 times smaller force on the model."),
P("Creeping-flow sphere with Re=0.1. Find drag coefficient CD.", "CD = 240", "CD = 24/Re (Stokes)", "CD = 24/0.1 = 240. Stokes drag regime: CD varies inversely with Re, drag ∝ v (not v²)."),
P("Airfoil: L=2000 N, ρ=1.2, V=30 m/s, planform area 4 m². Find lift coefficient.", "CL = 0.926", "L = CL×(½ρV²A)", "½ρV² = 0.5×1.2×900 = 540 Pa. CL = 2000/(540×4) = 2000/2160 = 0.926 (dimensionless)."),
P("Car: drag D=500 N, ρ=1.2, V=25 m/s, frontal area 2 m². Find CD.", "CD = 0.667", "D = CD×(½ρV²A)", "½ρV² = 0.5×1.2×625 = 375 Pa. CD = 500/(375×2) = 500/750 = 0.667."),
P("Capillary tube r=0.5 mm in water: σ=0.073 N/m, full wetting. Find capillary rise.", "h = 29.8 mm", "h = 2σcosθ/(ρgr)", "h = 2×0.073×1/(1000×9.81×0.0005) = 0.146/4.905 = 0.0298 m = 29.8 mm. Rise falls inversely with radius."),
P("Water has μ=0.001 Pa·s, ρ=1000. Find kinematic viscosity.", "ν = 10⁻⁶ m²/s", "ν = μ/ρ", "ν = 0.001/1000 = 1×10⁻⁶ m²/s = 1 cSt. Air at STP has ν ≈ 1.5×10⁻⁵ m²/s — about 15× larger."),
P("Fluid between plates: velocity gradient 10 s⁻¹ produces shear stress 5 Pa. Find dynamic viscosity.", "μ = 0.5 Pa·s", "τ = μ(du/dy)", "μ = 5/10 = 0.5 Pa·s. Straight τ–du/dy line → Newtonian fluid."),
P("Plate slides over a 0.5 mm oil film at 2 m/s. Find the velocity gradient.", "du/dy = 4000 s⁻¹", "du/dy = v/gap", "du/dy = 2/0.0005 = 4000 s⁻¹. Shear stress = μ×4000; opposite plate at rest."),
P("Tank area 1 m², orifice area 0.001 m² (Cd=0.62) drains from head 1 m to 0. Find emptying time.", "t ≈ 728 s", "t = 2A√H/(Cd·a·√(2g))", "√(2g) = 4.429. t = 2×1×√1/(0.62×0.001×4.429) = 2/0.002746 = 728 s ≈ 12.1 min. Time ∝ √(initial head)."),
P("Pipe bend 180°: water Q=0.1 m³/s in 300 mm pipe. Find force required to hold the bend (losses ignored).", "F = 283 N", "F = 2ρQv (U-turn reverses momentum)", "A = π×0.15² = 0.0707 m², v = 0.1/0.0707 = 1.415 m/s. F = 2×1000×0.1×1.415 = 283 N. The 180° reversal doubles the momentum change."),
P("Free jet strikes a stationary vertical flat plate: A=0.005 m², v=10 m/s. Find force.", "F = 500 N", "F = ρAv²", "F = 1000×0.005×100 = 500 N. Full velocity is destroyed normal to the plate."),
P("Same jet (A=0.005 m², v=10 m/s) hits a plate moving away at u=4 m/s. Find force.", "F = 180 N", "F = ρA(v−u)²", "F = 1000×0.005×(10−4)² = 5×36 = 180 N. Relative velocity controls momentum change; work is done on the moving plate."),
P("Water hammer: velocity 1 m/s, celerity c=1400 m/s in a steel pipe. Find pressure rise on sudden valve closure.", "Δp = 1.4 MPa", "Δp = ρcv", "Δp = 1000×1400×1 = 1.4×10⁶ Pa = 1.4 MPa ≈ 14 bar. Slow closure or surge tanks reduce this transient."),
P("Pelton turbine: Q=0.5 m³/s, head 100 m, efficiency 90%. Find power output.", "P = 441 kW", "P = ρQgH×η", "P = 1000×0.5×9.81×100×0.9 = 441450 W = 441 kW. Hydraulic power = ρQgH = 490.5 kW."),
P("Pump delivers Q=0.02 m³/s against 20 m head at 75% efficiency. Find input power.", "P = 5.23 kW", "P = ρQgH/η", "P = 1000×0.02×9.81×20/0.75 = 3924/0.75 = 5232 W = 5.23 kW."),
P("Find gauge pressure at 10 m depth in the open sea.", "p = 98.1 kPa", "p = ρgh", "p = 1000×9.81×10 = 98100 Pa = 98.1 kPa. Every 10 m of water adds ≈ 1 atm."),
P("Mercury barometer reads 760 mm. Find the corresponding pressure.", "p = 101.4 kPa", "p = ρ_Hg×g×h", "p = 13600×9.81×0.76 = 101396 Pa = 101.4 kPa. This is standard atmospheric pressure."),
P("Air has μ=1.8×10⁻⁵ Pa·s and ν=1.5×10⁻⁵ m²/s. Find density.", "ρ = 1.2 kg/m³", "ρ = μ/ν", "ρ = 1.8e-5/1.5e-5 = 1.2 kg/m³. Air density ~1.225 at STP; ~0.41× smaller at 0.84 bar altitude."),
P("Gauge at 35 m depth in the sea (ρ=1025? use 1000). Gauge pressure and absolute (p_atm=101 kPa).", "p_gage = 343 kPa, p_abs = 444 kPa", "p = ρgh; p_abs = p_gage + p_atm", "p_gage = 9810×35 = 343350 Pa = 343.4 kPa. p_abs = 343.4+101 = 444.4 kPa. Absolute used for cavitation analysis."),
P("Rectangular notch: if head h is doubled, by what factor does Q increase?", "Q × 2.83", "Q ∝ h^(3/2)", "For the same notch and Cd: Q₂/Q₁ = (2h/h)^1.5 = 2^1.5 = 2.828. Discharge is very sensitive to head."),
P("Triangular notch: if head is doubled, by what factor does Q increase?", "Q × 5.66", "Q ∝ h^(5/2)", "Q₂/Q₁ = 2^2.5 = √32 = 5.657. Triangular weirs amplify head changes more than rectangular weirs."),
P("Venturi: d₁=150 mm, d₂=75 mm, Q=0.03 m³/s water. Find throat pressure drop.", "Δp = 21.6 kPa", "Δp = ½ρ(v₂²−v₁²)", "A₁=0.01767, v₁=1.70; A₂=0.004418, v₂=6.79 m/s. Δp = 0.5×1000×(46.1−2.89) = 21610 Pa = 21.6 kPa. p₂ = p₁ − 21.6 kPa."),
P("Orifice jet area contracts to 0.62× orifice area. Find the coefficient of contraction Cc.", "Cc = 0.62", "Cc = A_jet/A_orifice", "Cc = A_jet/A_o = 0.62. Vena contracta shrinks the jet; combined with Cv≈0.98 gives typical Cd≈0.6."),
P("Upstream depth 0.5 m, velocity 6 m/s in a rectangular channel. Find the conjugate depth y₂ after the jump.", "y₂ ≈ 1.68 m", "Fr₁ = v/√(gy₁); y₂/y₁ = ½(√(1+8Fr₁²)−1)", "Fr₁ = 6/√(9.81×0.5) = 6/2.215 = 2.71. y₂ = 0.5×½(√(1+8×7.34)−1) = 0.5×½(√59.7−1) = 0.5×3.364 = 1.68 m."),
P("Channel friction factor f=0.02. Find Chezy coefficient C.", "C = 62.6 m^(1/2)/s", "C = √(8g/f)", "C = √(8×9.81/0.02) = √3924 = 62.6. Chezy velocity v = C√(RS)."),
P("Rectangular channel b=2 m, y=1 m. Find hydraulic radius.", "R = 0.5 m", "R = A/P, P = b+2y", "A = 2×1 = 2 m². P = 2+2×1 = 4 m. R = 2/4 = 0.5 m."),
P("Laminar pipe flow with mean velocity 1 m/s. Find the maximum velocity at the centreline.", "v_max = 2 m/s", "Laminar parabolic profile: v_max = 2v̄", "For fully developed laminar flow the velocity profile is parabolic: v_max = 2×v̄ = 2 m/s. In turbulent flow v_max ≈ 1.2×v̄."),
P("U-tube manometer shows h=0.15 m of an unknown liquid under p=3000 Pa (above atmosphere). Find its density.", "ρ ≈ 2039 kg/m³", "p = ρgh", "ρ = 3000/(9.81×0.15) = 3000/1.4715 = 2039 kg/m³. Compare: water 1000, mercury 13600."),
P("Semi-circular (180°) curved plate in a jet: A=0.002 m², v=15 m/s. Find force.", "F = 900 N", "F = 2ρAv²", "F = 2×1000×0.002×225 = 900 N. Turning the jet 180° doubles the force compared to a flat plate."),
P("Venturimeter: d₁=300 mm, d₂=150 mm, Δh=0.2 m water, Cd=0.97. Find discharge.", "Q ≈ 0.0351 m³/s", "Q = Cd×A₁A₂/√(A₁²−A₂²)×√(2gΔh)", "A₁=0.07069, A₂=0.01767 m². A₁A₂=1.2489e-3, √(A₁²−A₂²)=0.06845. Q_ideal = (1.2489e-3/0.06845)×1.981 = 0.03614. Q = 0.97×0.03614 = 0.0351 m³/s."),
P("Bernoulli: pipe d₁=0.2 m, d₂=0.1 m, Q=0.03 m³/s, p₁=120 kPa. Find p₂ (water, horizontal).", "p₂ ≈ 113.2 kPa", "p₁ + ½ρv₁² = p₂ + ½ρv₂²", "A₁=0.0314, v₁=0.955; A₂=0.00785, v₂=3.82 m/s. Δp = ½×1000×(14.59−0.912) = 6839 Pa. p₂ = 120000−6839 = 113161 Pa = 113.2 kPa."),
P("Coefficient of velocity: orifice under head H=0.1 m; jet centreline lands x=0.19 m at a fall y=0.1 m. Find Cv.", "Cv ≈ 0.95", "t = √(2y/g); v_actual = x/t; v_theory = √(2gH)", "Fall time t = √(2×0.1/9.81) = 0.1428 s. v_actual = 0.19/0.1428 = 1.331 m/s. v_theory = √(2×9.81×0.1) = 1.401 m/s. Cv = 1.331/1.401 = 0.95. The trajectory method measures velocity loss in the orifice."),
P("Capillary: same fluid, tubes r=0.4 mm and r=0.2 mm. How does rise compare?", "h₂ = 2×h₁", "h ∝ 1/r", "h = 2σ/(ρgr) → rise inversely proportional to radius. Halving radius doubles the rise: 0.2 mm tube gives twice the rise of the 0.4 mm tube."),
P("Rectangular channel b=2 m carries Q=10 m³/s. Find critical depth.", "y_c = 1.37 m", "y_c = (q²/g)^(1/3), q = Q/b", "q = 10/2 = 5 m²/s. y_c = (25/9.81)^(1/3) = (2.548)^(1/3) = 1.366 m ≈ 1.37 m."),
P("Buoyant sphere d=0.3 m floating half-submerged in water. Find buoyant force.", "F_B = 69.3 N", "F_B = γ×V_sub = γ×½×(4/3)πr³", "V = (4/3)π×0.15³ = 0.01414 m³. V_sub = 0.00707 m³. F_B = 9810×0.00707 = 69.3 N. Body weight equals this."),
P("Ship: BM=0.6 m, G is 0.4 m above B. Find GM and state stability.", "GM = 0.2 m (stable)", "GM = BM − BG", "GM = 0.6 − 0.4 = 0.2 m > 0 → stable (righting moment for small angles). Metacentric height is the universal stability measure."),
P("Vehicle: drag force 500 N at 20 m/s. Find power to overcome drag.", "P = 10 kW", "P = F_D×v", "P = 500×20 = 10000 W = 10 kW. Drag power scales with v³ for fixed CD."),
P("Vertical dam face, water depth 12 m. Find force per metre width and its point of application.", "F = 706 kN/m at 4 m below surface", "F = ½γh²; acts at h/3 from base", "F = ½×9810×144 = 706320 N/m = 706 kN/m. Resultant at h/3 = 4 m below the surface (8 m above base)."),
P("Jet Q=0.05 m³/s at v₁=20 m/s strikes a stationary plate. Find force (momentum method).", "F = 1000 N", "F = ρQ(v₁−v₂); v₂=0", "F = 1000×0.05×20 = 1000 N. Mass rate ρQ = 50 kg/s; velocity destroyed 20 m/s."),
P("Same jet (Q=0.05, v=20) hits a blade moving at u=8 m/s. Find force on the blade.", "F = 600 N", "F = ρQ(v−u)", "F = 1000×0.05×(20−8) = 50×12 = 600 N. Relative velocity 12 m/s governs the impulse."),
P("Duct carries air (ρ=1.2) at 10 m/s through area 0.5 m². Find mass flow rate.", "ṁ = 6 kg/s", "ṁ = ρAV", "ṁ = 1.2×0.5×10 = 6 kg/s. Volume flow = 5 m³/s."),
P("Two pipes in series (equal length 200 m) with d=0.2 m and 0.15 m, same f. Find equivalent single-pipe diameter over 400 m.", "d_eq ≈ 0.165 m", "L_eq/d_eq⁵ = Σ(Lᵢ/dᵢ⁵)", "d_eq⁵ = 400/(200/0.2⁵ + 200/0.15⁵) = 400/(625000+2633745) = 400/3258745 = 1.227e-4 → d_eq = 0.165 m. Series pipes resist more than either alone."),
P("What water-column height produces a pressure of 100 kPa?", "h = 10.19 m", "h = p/ρg", "h = 100000/9810 = 10.19 m. One standard atmosphere supports 10.33 m of water."),
P("Pitot/static on an aircraft: dynamic pressure Δp=240 Pa in air at? Find equivalent velocity (ρ=1.2).", "v = 20 m/s", "Δp = ½ρv²", "v = √(2×240/1.2) = √400 = 20 m/s. Dynamic pressure grows as v², so indicated speed (airspeed) is sensitive."),
P("Bluff sphere falling fast (Re > 10³, turbulent wake). Give the standard drag coefficient CD.", "CD ≈ 0.44", "Self-similar turbulent wake regime", "CD = 0.44 for a smooth sphere in the range Re ≈ 10³ to 2×10⁵. Below Re≈1 (Stokes), CD = 24/Re; near Re≈10⁵ it drops sharply (drag crisis)."),
P("At what Reynolds number does transition from laminar to turbulent plate boundary layer typically occur?", "Re_x ≈ 5×10⁵", "Transition criterion on a smooth flat plate", "Transition typically begins near Re_x = 3–5×10⁵ (with free-stream turbulence it can be lower). Designers use Re = 5×10⁵ as the switch point."),
P("Laminar entry length in a pipe: find l_e/d for Re=1000.", "l_e = 50d", "l_e = 0.05×Re×d", "l_e = 0.05×1000×d = 50d. For turbulent flow l_e ≈ 10–30d. Beyond l_e the profile is fully developed."),
P("Keeping Q constant, the pipe diameter is halved. How does Reynolds number change?", "Re doubles", "Re = 4ρQ/(πμd)", "Re ∝ 1/d at constant Q: halving d doubles Re. Beware: doubling v alone doubles Re only if d stays same."),
];
  if (typeof module !== "undefined" && module.exports) module.exports = SSC_JE_ENC2_TOMFLUIDS;
  if (typeof window !== "undefined") window.SSC_JE_ENC2_TOMFLUIDS = SSC_JE_ENC2_TOMFLUIDS;
})();
